/* @autogenerated */
import {
  AfterViewInit,
  Component,
  effect,
  ElementRef,
  input,
  OnDestroy,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatButtonModule } from '@angular/material/button';
import { MatButtonToggleModule } from '@angular/material/button-toggle';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltipModule } from '@angular/material/tooltip';
import { DisplayProvider } from '@shared/data/display-provider';
import { SelectionModel } from '@shared/data/selection-model';

export interface GanttItemMapper<T> {
  id(item: T): string;
  label(item: T): string;
  start(item: T): Date;
  end(item: T): Date;
  progress?(item: T): number;
  color?(item: T): string;
  dependencies?(item: T): string[];
}

export type GanttViewMode = 'Day' | 'Week' | 'Month' | 'Quarter Day' | 'Half Day';

@Component({
  selector: 'gantt-view',
  standalone: true,
  imports: [
    CommonModule,
    MatProgressBarModule,
    MatButtonModule,
    MatButtonToggleModule,
    MatIconModule,
    MatTooltipModule,
  ],
  templateUrl: './gantt-view.component.html',
  styleUrls: ['./gantt-view.component.scss'],
})
export class GanttViewComponent implements AfterViewInit, OnDestroy {
  data = input.required<any[] | undefined>();
  mapper = input.required<GanttItemMapper<any>>();
  display = input<DisplayProvider<any>>();
  searching = input<boolean>();
  selectionModel = input<SelectionModel<any> | undefined>();
  initialMode = input<GanttViewMode>('Week');
  readonly = input<boolean>(false);

  next = output<void>();
  activate = output<any>();
  dateChange = output<{ item: any; start: Date; end: Date }>();
  progressChange = output<{ item: any; progress: number }>();

  readonly ganttEl = viewChild.required<ElementRef<HTMLDivElement>>('ganttContainer');
  readonly viewMode = signal<GanttViewMode>('Week');
  readonly modes: GanttViewMode[] = ['Day', 'Week', 'Month'];

  private gantt: any = null;
  private itemMap = new Map<string, any>();

  constructor() {
    effect(() => {
      this.viewMode.set(this.initialMode());
    });
    effect(() => {
      const data = this.data();
      if (this.gantt) {
        this.refreshTasks(data ?? []);
      }
    });
    effect(() => {
      const mode = this.viewMode();
      if (this.gantt) {
        this.gantt.change_view_mode(mode);
      }
    });
  }

  async ngAfterViewInit(): Promise<void> {
    await this.initGantt();
  }

  ngOnDestroy(): void {
    this.gantt = null;
  }

  private async initGantt(): Promise<void> {
    const { default: Gantt } = await import('frappe-gantt');
    const el = this.ganttEl().nativeElement;
    const tasks = this.buildTasks(this.data() ?? []);

    if (tasks.length === 0) {
      this.gantt = null;
      return;
    }

    this.gantt = new Gantt(el, tasks, {
      view_mode: this.viewMode(),
      date_format: 'YYYY-MM-DD',
      language: 'es',
      readonly: this.readonly(),
      on_click: (task: any) => {
        const item = this.itemMap.get(task.id);
        if (item) {
          this.activate.emit(item);
        }
      },
      on_date_change: (task: any, start: Date, end: Date) => {
        const item = this.itemMap.get(task.id);
        if (item) {
          this.dateChange.emit({ item, start, end });
        }
      },
      on_progress_change: (task: any, progress: number) => {
        const item = this.itemMap.get(task.id);
        if (item) {
          this.progressChange.emit({ item, progress });
        }
      },
    });
  }

  private refreshTasks(items: any[]): void {
    if (!this.gantt) return;
    const tasks = this.buildTasks(items);
    this.gantt.refresh(tasks);
  }

  private buildTasks(items: any[]): any[] {
    const m = this.mapper();
    this.itemMap.clear();
    return items.map((item) => {
      const id = m.id(item);
      this.itemMap.set(id, item);
      return {
        id,
        name: m.label(item),
        start: this.formatDate(m.start(item)),
        end: this.formatDate(m.end(item)),
        progress: m.progress?.(item) ?? 0,
        dependencies: (m.dependencies?.(item) ?? []).join(', '),
        custom_class: m.color?.(item) ? `gantt-task--custom` : '',
      };
    });
  }

  private formatDate(d: Date): string {
    const y = d.getFullYear();
    const mo = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${mo}-${day}`;
  }

  setViewMode(mode: GanttViewMode): void {
    this.viewMode.set(mode);
  }
}
